/**
 * The iOS "touch icon" in two versions, embedded so a route can pick one per request.
 *
 * Every browser on iPhone — Safari, Chrome, Firefox — takes its tab/Favorites icon from the
 * same apple-touch-icon address, and iOS paints a transparent one black. Safari also
 * handles a transparent one unreliably. So Safari is served the opaque square (crown on the
 * site colour) and every other browser the transparent crown. Regenerate from the source
 * image rather than editing these by hand.
 */
export const TOUCH_ICON_OPAQUE = "";
export const TOUCH_ICON_TRANSPARENT = "";
